function deg(r){ return r*180/Math.PI; }
function lawCosAngle(opp, a, b){ var c=(a*a+b*b-opp*opp)/(2*a*b); if(c<-1) c=-1; if(c>1) c=1; return deg(Math.acos(c)); }
function areaHeron(a, b, c){ var s=(a+b+c)/2; var v=s*(s-a)*(s-b)*(s-c); return v>0? Math.sqrt(v): NaN; }
function solveSSS(a, b, c){
  if(!(a>0&&b>0&&c>0)) return null;
  if(a+b<=c || a+c<=b || b+c<=a) return null; // triangle inequality
  var A=lawCosAngle(a,b,c), B=lawCosAngle(b,a,c), C=lawCosAngle(c,a,b);
  return {A:A, B:B, C:C, area:areaHeron(a,b,c)};
}
function solveSAS(a, b, Cdeg){ // sides a,b with included angle C
  if(!(a>0&&b>0)) return null;
  var Cr=Cdeg*Math.PI/180; var c=Math.sqrt(a*a+b*b-2*a*b*Math.cos(Cr));
  var A=lawCosAngle(a,b,c), B=lawCosAngle(b,a,c);
  return {A:A, B:B, C:Cdeg, c:c, area:0.5*a*b*Math.sin(Cr)};
}
var EXPORTS = { solveSSS:solveSSS, solveSAS:solveSAS, areaHeron:areaHeron, lawCosAngle:lawCosAngle };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TriangleForgePure = EXPORTS; }
